def post_tahrirlash(request, post_id):
    post = get_object_or_404(Post, id=post_id)

    if request.method == 'POST':
        forma = PostForma(request.POST, instance=post)
        if forma.is_valid():
            forma.save()
            return redirect('post_batafsil', post_id=post.id)
