from typing import Annotated
from fastapi import Cookie, Depends, HTTPException

def sessiya_tekshirish(sessiya_id: Annotated[str | None, Cookie()] = None) -> str:
    if not sessiya_id:
        raise HTTPException(401, "Sessiya topilmadi, avval tizimga kiring")
    return sessiya_id

def admin_ekanini_tekshirish(sessiya_id: Annotated[str, Depends(sessiya_tekshirish)]) -> str:
    if sessiya_id != "admin-sessiya":
        raise HTTPException(403, "Faqat administratorlar uchun ruxsat berilgan")
    return sessiya_id

@app.delete("/mahsulotlar/{mahsulot_id}")
def ochirish(mahsulot_id: int, _admin: Annotated[str, Depends(admin_ekanini_tekshirish)]):
    return {"xabar": f"Mahsulot {mahsulot_id} o'chirildi"}
